import Foundation

enum InstallMethod: String, CaseIterable, Identifiable {
    /// Local HTTPS when a valid server certificate exists, otherwise semi-local.
    case automatic
    /// Everything served from the phone over HTTPS (needs a trusted cert for a 127.0.0.1 hostname).
    case localHTTPS
    /// IPA served from the phone over HTTP; manifest generated by api.palera.in over HTTPS.
    case semiLocal

    var id: String { rawValue }

    var title: String {
        switch self {
        case .automatic: return "Automatic"
        case .localHTTPS: return "Fully Local (HTTPS)"
        case .semiLocal: return "Semi-Local"
        }
    }

    /// Fits a 3-segment control on the smallest iPhone.
    var shortTitle: String {
        switch self {
        case .automatic: return "Automatic"
        case .localHTTPS: return "Local"
        case .semiLocal: return "Semi-Local"
        }
    }

    var detail: String {
        switch self {
        case .automatic:
            return "Uses Fully Local when a valid server certificate is available, otherwise Semi-Local."
        case .localHTTPS:
            return "The manifest and IPA are served from this iPhone over HTTPS. Needs a valid certificate (backloop.dev or your own domain)."
        case .semiLocal:
            return "The IPA is served from this iPhone; only the small manifest comes from api.palera.in (needs internet)."
        }
    }
}

/// Builds itms-services manifests and links. Plain Foundation, unit-testable.
enum InstallManifest {
    static func data(packageURL: URL, bundleID: String, version: String, title: String,
                     displayImageURL: URL? = nil, fullSizeImageURL: URL? = nil) -> Data {
        var assets: [[String: Any]] = [["kind": "software-package", "url": packageURL.absoluteString]]
        if let displayImageURL { assets.append(["kind": "display-image", "url": displayImageURL.absoluteString]) }
        if let fullSizeImageURL { assets.append(["kind": "full-size-image", "url": fullSizeImageURL.absoluteString]) }
        let manifest: [String: Any] = [
            "items": [[
                "assets": assets,
                "metadata": [
                    "bundle-identifier": bundleID,
                    "bundle-version": version,
                    "kind": "software",
                    "title": title
                ]
            ]]
        ]
        return (try? PropertyListSerialization.data(fromPropertyList: manifest, format: .xml, options: 0)) ?? Data()
    }

    /// External manifest generator used by Feather's "semi-local" mode.
    static func paleraManifestURL(packageURL: URL, bundleID: String, version: String, title: String) -> URL? {
        var components = URLComponents(string: "https://api.palera.in/genPlist")
        components?.queryItems = [
            URLQueryItem(name: "bundleid", value: bundleID),
            URLQueryItem(name: "name", value: title),
            URLQueryItem(name: "version", value: version),
            URLQueryItem(name: "fetchurl", value: packageURL.absoluteString)
        ]
        // URLComponents leaves "+" alone; encode it so it isn't read as a space.
        let encodedQuery = components?.percentEncodedQuery?.replacingOccurrences(of: "+", with: "%2B")
        components?.percentEncodedQuery = encodedQuery
        return components?.url
    }

    static func itmsURL(manifestURL: URL) -> URL? {
        guard let encoded = manifestURL.absoluteString.addingPercentEncoding(withAllowedCharacters: .alphanumerics) else { return nil }
        return URL(string: "itms-services://?action=download-manifest&url=\(encoded)")
    }
}
